CustomField.formula:
TEXT(
    IF(
        MOD(
            HOUR(
                TIMEVALUE(Unformatted_Appointment_Time__c)
            ), 
            12
        ) = 0,
        12,
        MOD(
            HOUR(
                TIMEVALUE(Unformatted_Appointment_Time__c)
            ), 
            12
        )
    )
) & ":" &
RIGHT(
    "0" & TEXT(
        MINUTE(
            TIMEVALUE(Unformatted_Appointment_Time__c)
        )
    ), 
    2
) & " " &
IF(
    HOUR(
        TIMEVALUE(Unformatted_Appointment_Time__c)
    ) < 12,
    "AM",
    "PM"
)
